wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(38007966321043715216)
,p_event_id=>wwv_flow_imp.id(38007966238485715215)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '',
    '(function () {',
    '    const fuelId = $v("P13_FUEL_STOCK_ID");',
    '',
    '    const entered = String(',
    '        $v("P13_LITERS_SOLD") || ""',
    '    ).trim();',
    '',
    '    const stockText = String(',
    '        $v("P13_AVAILABLE_LITERS") || ""',
    '    ).replace(/,/g, "");',
    '',
    '    const liters = Number(entered);',
    '    const available = Number(stockText);',
    '',
    '    apex.message.clearErrors();',
    '',
    '    if (entered === "") {',
    '        return;',
    '    }',
    '',
    '    let error = "";',
    '',
    '    if (!fuelId) {',
    '        error = "Please select a fuel type first.";',
    '',
    '    } else if (!Number.isFinite(liters) || liters < 0.01) {',
    '        error = "Liters Sold must be at least 0.01.";',
    '',
    '    } else if (liters !== Number(liters.toFixed(2))) {',
    '        error = "Liters Sold cannot have more than 2 decimal places.";',
    '',
    '    } else if (stockText === "" || !Number.isFinite(available)) {',
    '        error = "Available fuel stock could not be loaded.";',
    '',
    '    } else if (liters > available) {',
    '        error = "Insufficient fuel stock. Only " +',
    '                available + " liters are available.";',
    '    }',
    '',
    '    if (error) {',
    '        apex.message.showErrors([{',
    '            type: "error",',
    '            location: ["inline"],',
    '            pageItem: "P13_LITERS_SOLD",',
    '            message: error,',
    '            unsafe: false',
    '        }]);',
    '    }',
    '})();',
    '')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20261010051043Z')
,p_updated_on=>wwv_flow_imp.dz('20261010084049Z')
,p_created_by=>'2402230002@STUDENTS.STAMFOED.EDU'
,p_updated_by=>'2402230002@STUDENTS.STAMFOED.EDU'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(38007968511826715238)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add Product to Cart'
,p_static_id=>'add-product-to-cart'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    v_product_id     NUMBER;',
'    v_product_name   VARCHAR2(100);',
'    v_quantity       NUMBER;',
'    v_stock          NUMBER;',
'    v_price          NUMBER;',
'    v_existing_seq   NUMBER;',
'    v_existing_qty   NUMBER;',
'BEGIN',
'    -- 1. Check product selection',
'    IF :P13_PRODUCT_ID IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20021, ''Please select a product.''',
'        );',
'    END IF;',
'',
'    -- 2. Validate quantity',
'    BEGIN',
'        v_quantity := TO_NUMBER(:P13_PRODUCT_QUANTITY);',
'    EXCEPTION',
'        WHEN VALUE_ERROR OR INVALID_NUMBER THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20022, ''Enter a valid quantity.''',
'            );',
'    END;',
'',
'    IF v_quantity IS NULL',
'       OR v_quantity < 1',
'       OR v_quantity <> TRUNC(v_quantity) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20023, ''Quantity must be a positive whole number.''',
'        );',
'    END IF;',
'',
'    -- 3. Retrieve actual product details',
'    SELECT',
'        product_id,',
'        product_name,',
'        stock_quantity,',
'        selling_price',
'    INTO',
'        v_product_id,',
'        v_product_name,',
'        v_stock,',
'        v_price',
'    FROM PRODUCT_ITEM',
'    WHERE product_id = :P13_PRODUCT_ID',
'      AND status = ''Available'';',
'',
'    -- 4. Create cart if it does not exist',
'    IF NOT APEX_COLLECTION.COLLECTION_EXISTS(',
'        p_collection_name => ''POS_PRODUCT_CART''',
'    ) THEN',
'        APEX_COLLECTION.CREATE_COLLECTION(',
'            p_collection_name => ''POS_PRODUCT_CART''',
'        );',
'    END IF;',
'',
'    -- 5. Check whether product is already in cart',
'    SELECT',
'        MAX(seq_id),',
'        NVL(SUM(n002), 0)',
'    INTO',
'        v_existing_seq,',
'        v_existing_qty',
'    FROM APEX_COLLECTIONS',
'    WHERE collection_name = ''POS_PRODUCT_CART''',
'      AND n001 = v_product_id;',
'',
'    -- 6. Prevent adding more than current stock',
'    IF v_existing_qty + v_quantity > v_stock THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20024,',
'            ''Insufficient stock. Available: ''',
'            || v_stock || '' units.''',
'        );',
'    END IF;',
'',
'    -- 7. Add new product or increase existing quantity',
'    IF v_existing_seq IS NULL THEN',
'',
'        APEX_COLLECTION.ADD_MEMBER(',
'            p_collection_name => ''POS_PRODUCT_CART'',',
'            p_c001            => v_product_name,',
'            p_n001            => v_product_id,',
'            p_n002            => v_quantity,',
'            p_n003            => v_price',
'        );',
'',
'    ELSE',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''POS_PRODUCT_CART'',',
'            p_seq             => v_existing_seq,',
'            p_attr_number     => 2,',
'            p_number_value    => v_existing_qty + v_quantity',
'        );',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''POS_PRODUCT_CART'',',
'            p_seq             => v_existing_seq,',
'            p_attr_number     => 3,',
'            p_number_value    => v_price',
'        );',
'',
'    END IF;',
'',
'    -- 8. Clear quantity for the next addition',
'    :P13_PRODUCT_QUANTITY := NULL;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20025, ''Selected product is unavailable.''',
'        );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(38007968439248715237)
,p_process_success_message=>'Product added to shopping cart successfully.'
,p_internal_uid=>38007968511826715238
,p_created_on=>wwv_flow_imp.dz('20261010140317Z')
,p_updated_on=>wwv_flow_imp.dz('20261010140317Z')
,p_created_by=>'2402230002@STUDENTS.STAMFOED.EDU'
,p_updated_by=>'2402230002@STUDENTS.STAMFOED.EDU'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(38007967126543715224)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Fuel Sale'
,p_static_id=>'process-fuel-sale'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    v_liters       NUMBER;',
'    v_stock        NUMBER;',
'    v_price        NUMBER;',
'    v_total        NUMBER;',
'    v_count        NUMBER;',
'BEGIN',
'    -- 1. Verify employee',
'    IF :P13_EMPLOYEE_ID IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002, ''Please select an employee.''',
'        );',
'    END IF;',
'',
'    SELECT COUNT(*)',
'    INTO v_count',
'    FROM EMPLOYEE',
'    WHERE employee_id = :P13_EMPLOYEE_ID',
'      AND status = ''Active'';',
'',
'    IF v_count = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20003, ''Employee is not active or does not exist.''',
'        );',
'    END IF;',
'',
'    -- 2. Verify optional customer',
'    IF :P13_CUSTOMER_ID IS NOT NULL THEN',
'        SELECT COUNT(*)',
'        INTO v_count',
'        FROM CUSTOMER',
'        WHERE customer_id = :P13_CUSTOMER_ID',
'          AND status = ''Active'';',
'',
'        IF v_count = 0 THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20004, ''Selected customer is not active.''',
'            );',
'        END IF;',
'    END IF;',
'',
'    -- 3. Verify fuel selection',
'    IF :P13_FUEL_STOCK_ID IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20005, ''Please select a fuel type.''',
'        );',
'    END IF;',
'',
'    -- 4. Validate liters',
'    BEGIN',
'        v_liters := TO_NUMBER(:P13_LITERS_SOLD);',
'    EXCEPTION',
'        WHEN INVALID_NUMBER OR VALUE_ERROR THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20006, ''Enter a valid numeric fuel quantity.''',
'            );',
'    END;',
'',
'    IF v_liters IS NULL',
'       OR v_liters <= 0',
'       OR v_liters <> ROUND(v_liters, 2)',
'       OR v_liters > 999999.99 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20007,',
'            ''Enter a valid positive quantity with at most 2 decimals.''',
'        );',
'    END IF;',
'',
'    -- 5. Verify payment method',
'    IF :P13_PAYMENT_METHOD IS NULL',
'       OR :P13_PAYMENT_METHOD NOT IN (''Cash'', ''Card'', ''QR'') THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20008, ''Please select Cash, Card, or QR.''',
'        );',
'    END IF;',
'',
'    -- 6. Lock stock and retrieve current database price',
'    SELECT',
'        fs.current_liters,',
'        ft.price_per_liter',
'    INTO',
'        v_stock,',
'        v_price',
'    FROM FUEL_STOCK fs',
'    JOIN FUEL_TYPE ft',
'        ON fs.fuel_type_id = ft.fuel_type_id',
'    WHERE fs.fuel_stock_id = :P13_FUEL_STOCK_ID',
'      AND ft.status = ''Available''',
'    FOR UPDATE OF fs.current_liters;',
'',
'    -- 7. Prevent selling more than available',
'    IF v_liters > v_stock THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20009,',
'            ''Insufficient fuel. Available: ''',
'            || v_stock || '' liters.''',
'        );',
'    END IF;',
'',
'    -- 8. Calculate total using actual database price',
'    v_total := ROUND(v_liters * v_price, 2);',
'',
'    -- 9. Deduct actual fuel stock',
'    UPDATE FUEL_STOCK',
'    SET current_liters = current_liters - v_liters',
'    WHERE fuel_stock_id = :P13_FUEL_STOCK_ID',
'      AND current_liters >= v_liters;',
'',
'    IF SQL%ROWCOUNT <> 1 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20010, ''Fuel stock deduction failed.''',
'        );',
'    END IF;',
'',
'    -- 10. Insert actual fuel sale transaction',
'    INSERT INTO SALE (',
'        employee_id,',
'        customer_id,',
'        fuel_stock_id,',
'        liters_sold,',
'        total_amount,',
'        payment_method',
'    )',
'    VALUES (',
'        :P13_EMPLOYEE_ID,',
'        :P13_CUSTOMER_ID,',
'        :P13_FUEL_STOCK_ID,',
'        v_liters,',
'        v_total,',
'        :P13_PAYMENT_METHOD',
'    );',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20011, ''Selected fuel stock is unavailable.''',
'        );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(38007967013992715223)
,p_process_success_message=>'Fuel sale completed successfully. Inventory has been updated.'
,p_internal_uid=>38007967126543715224
,p_created_on=>wwv_flow_imp.dz('20261010073002Z')
,p_updated_on=>wwv_flow_imp.dz('20261010083555Z')
,p_created_by=>'2402230002@STUDENTS.STAMFOED.EDU'
,p_updated_by=>'2402230002@STUDENTS.STAMFOED.EDU'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(38007969644656715249)
,p_process_sequence=>30
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Product Sale'
,p_static_id=>'process-product-sale'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    v_order_id      NUMBER;',
'    v_grand_total   NUMBER := 0;',
'    v_stock         NUMBER;',
'    v_price         NUMBER;',
'    v_status        VARCHAR2(20);',
'    v_line_total    NUMBER;',
'    v_count         NUMBER;',
'',
'BEGIN',
'    --------------------------------------------------',
'    -- 1. VALIDATE EMPLOYEE',
'    --------------------------------------------------',
'    IF :P13_PRODUCT_EMPLOYEE_ID IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20041, ''Please select an employee.''',
'        );',
'    END IF;',
'',
'    SELECT COUNT(*)',
'    INTO v_count',
'    FROM EMPLOYEE',
'    WHERE employee_id = :P13_PRODUCT_EMPLOYEE_ID',
'      AND status = ''Active'';',
'',
'    IF v_count = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20042, ''Please select an active employee.''',
'        );',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- 2. VALIDATE OPTIONAL CUSTOMER',
'    --------------------------------------------------',
'    IF :P13_PRODUCT_CUSTOMER_ID IS NOT NULL THEN',
'',
'        SELECT COUNT(*)',
'        INTO v_count',
'        FROM CUSTOMER',
'        WHERE customer_id = :P13_PRODUCT_CUSTOMER_ID',
'          AND status = ''Active'';',
'',
'        IF v_count = 0 THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20043, ''Selected customer is not active.''',
'            );',
'        END IF;',
'',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- 3. VALIDATE PAYMENT METHOD',
'    --------------------------------------------------',
'    IF :P13_PRODUCT_PAYMENT_METHOD IS NULL',
'       OR :P13_PRODUCT_PAYMENT_METHOD',
'          NOT IN (''Cash'', ''Card'', ''QR'') THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20044,',
'            ''Please select Cash, Card, or QR.''',
'        );',
'',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- 4. CHECK SHOPPING CART',
'    --------------------------------------------------',
'    IF NOT APEX_COLLECTION.COLLECTION_EXISTS(',
'        p_collection_name => ''POS_PRODUCT_CART''',
'    ) THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20045, ''Shopping cart is empty.''',
'        );',
'',
'    END IF;',
'',
'    SELECT COUNT(*)',
'    INTO v_count',
'    FROM APEX_COLLECTIONS',
'    WHERE collection_name = ''POS_PRODUCT_CART'';',
'',
'    IF v_count = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20045, ''Shopping cart is empty.''',
'        );',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- 5. VALIDATE AND LOCK PRODUCT INVENTORY',
'    --------------------------------------------------',
'    FOR r IN (',
'        SELECT',
'            n001 AS product_id,',
'            SUM(n002) AS quantity,',
'            SUM(',
'                CASE',
'                    WHEN n002 IS NULL',
'                      OR n002 <= 0',
'                      OR n002 <> TRUNC(n002)',
'                    THEN 1',
'                    ELSE 0',
'                END',
'            ) AS invalid_lines',
'        FROM APEX_COLLECTIONS',
'        WHERE collection_name = ''POS_PRODUCT_CART''',
'        GROUP BY n001',
'        ORDER BY n001',
'    ) LOOP',
'',
'        IF r.product_id IS NULL',
'           OR r.invalid_lines > 0 THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20046,',
'                ''Invalid item or quantity in cart.''',
'            );',
'',
'        END IF;',
'',
'        BEGIN',
'',
'            SELECT',
'                stock_quantity,',
'                selling_price,',
'                status',
'            INTO',
'                v_stock,',
'                v_price,',
'                v_status',
'            FROM PRODUCT_ITEM',
'            WHERE product_id = r.product_id',
'            FOR UPDATE OF stock_quantity;',
'',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                RAISE_APPLICATION_ERROR(',
'                    -20047,',
'                    ''A product in the cart no longer exists.''',
'                );',
'        END;',
'',
'        IF NVL(v_status, ''?'') <> ''Available'' THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20048,',
'                ''A product is no longer available.''',
'            );',
'',
'        END IF;',
'',
'        --------------------------------------------------',
'        -- PREVENT SELLING MORE THAN AVAILABLE STOCK',
'        --------------------------------------------------',
'        IF NVL(v_stock, 0) < r.quantity THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20049,',
'                ''Insufficient stock for product ID ''',
'                || r.product_id',
'                || ''. Available: ''',
'                || NVL(v_stock, 0)',
'            );',
'',
'        END IF;',
'',
'        --------------------------------------------------',
'        -- CALCULATE TOTAL USING REAL DATABASE PRICE',
'        --------------------------------------------------',
'        v_grand_total := v_grand_total',
'            + ROUND(r.quantity * v_price, 2);',
'',
'    END LOOP;',
'',
'    IF v_grand_total <= 0',
'       OR v_grand_total > 99999999.99 THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20050, ''Invalid checkout total.''',
'        );',
'',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- 6. INSERT ONE PRODUCT SALE ORDER',
'    --------------------------------------------------',
'    INSERT INTO PRODUCT_SALE_ORDER (',
'        employee_id,',
'        customer_id,',
'        payment_method,',
'        grand_total',
'    )',
'    VALUES (',
'        :P13_PRODUCT_EMPLOYEE_ID,',
'        :P13_PRODUCT_CUSTOMER_ID,',
'        :P13_PRODUCT_PAYMENT_METHOD,',
'        v_grand_total',
'    )',
'    RETURNING product_sale_order_id',
'    INTO v_order_id;',
'',
'    --------------------------------------------------',
'    -- 7. DEDUCT STOCK AND INSERT PRODUCT SALE LINES',
'    --------------------------------------------------',
'    FOR r IN (',
'        SELECT',
'            n001 AS product_id,',
'            SUM(n002) AS quantity',
'        FROM APEX_COLLECTIONS',
'        WHERE collection_name = ''POS_PRODUCT_CART''',
'        GROUP BY n001',
'        ORDER BY n001',
'    ) LOOP',
'',
'        SELECT selling_price',
'        INTO v_price',
'        FROM PRODUCT_ITEM',
'        WHERE product_id = r.product_id;',
'',
'        v_line_total := ROUND(r.quantity * v_price, 2);',
'',
'        --------------------------------------------------',
'        -- UPDATE REAL PRODUCT INVENTORY',
'        --------------------------------------------------',
'        UPDATE PRODUCT_ITEM',
'        SET',
'            stock_quantity = stock_quantity - r.quantity,',
'            status = CASE',
'                WHEN stock_quantity = r.quantity',
'                THEN ''Out of Stock''',
'                ELSE status',
'            END',
'        WHERE product_id = r.product_id',
'          AND status = ''Available''',
'          AND stock_quantity >= r.quantity;',
'',
'        IF SQL%ROWCOUNT <> 1 THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20051,',
'                ''Product stock deduction failed.''',
'            );',
'',
'        END IF;',
'',
'        --------------------------------------------------',
'        -- INSERT REAL PRODUCT SALE DETAIL',
'        --------------------------------------------------',
'        INSERT INTO SALE_PRODUCT (',
'            employee_id,',
'            customer_id,',
'            product_id,',
'            quantity,',
'            total_amount,',
'            product_sale_order_id',
'        )',
'        VALUES (',
'            :P13_PRODUCT_EMPLOYEE_ID,',
'            :P13_PRODUCT_CUSTOMER_ID,',
'            r.product_id,',
'            r.quantity,',
'            v_line_total,',
'            v_order_id',
'        );',
'',
'    END LOOP;',
'',
'    --------------------------------------------------',
'    -- 8. CLEAR SHOPPING CART AFTER SUCCESSFUL CHECKOUT',
'    --------------------------------------------------',
'    APEX_COLLECTION.TRUNCATE_COLLECTION(',
'        p_collection_name => ''POS_PRODUCT_CART''',
'    );',
'',
'    --------------------------------------------------',
'    -- 9. RESET PRODUCT SALE FIELDS',
'    --------------------------------------------------',
'    :P13_PRODUCT_EMPLOYEE_ID    := NULL;',
'    :P13_PRODUCT_CUSTOMER_ID    := NULL;',
'    :P13_PRODUCT_ID             := NULL;',
'    :P13_PRODUCT_PRICE          := NULL;',
'    :P13_PRODUCT_QUANTITY       := NULL;',
'    :P13_PRODUCT_PAYMENT_METHOD := NULL;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(38007969581532715248)
,p_process_success_message=>'Product sale completed successfully. Inventory has been updated.'
,p_internal_uid=>38007969644656715249
,p_created_on=>wwv_flow_imp.dz('20261010154153Z')
,p_updated_on=>wwv_flow_imp.dz('20261010154940Z')
,p_created_by=>'2402230002@STUDENTS.STAMFOED.EDU'
,p_updated_by=>'2402230002@STUDENTS.STAMFOED.EDU'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(38007969382403715246)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Remove Product from Cart'
,p_static_id=>'remove-product-from-cart'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    v_seq_id NUMBER;',
'BEGIN',
'    -- Validate the selected cart row',
'    IF :P13_REMOVE_SEQ IS NULL',
'       OR NOT REGEXP_LIKE(',
'           :P13_REMOVE_SEQ, ''^[0-9]{1,10}$''',
'       )',
'    THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20031, ''Invalid shopping cart item.''',
'        );',
'    END IF;',
'',
'    v_seq_id := TO_NUMBER(:P13_REMOVE_SEQ);',
'',
'    -- Remove only from the current session cart',
'    IF APEX_COLLECTION.COLLECTION_EXISTS(',
'        p_collection_name => ''POS_PRODUCT_CART''',
'    ) THEN',
'        APEX_COLLECTION.DELETE_MEMBER(',
'            p_collection_name => ''POS_PRODUCT_CART'',',
'            p_seq             => v_seq_id',
'        );',
'    END IF;',
'',
'    -- Clear the temporary selected row',
'    :P13_REMOVE_SEQ := NULL;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'REMOVE_CART_ITEM'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>38007969382403715246
,p_created_on=>wwv_flow_imp.dz('20261010145220Z')
,p_updated_on=>wwv_flow_imp.dz('20261010145220Z')
,p_created_by=>'2402230002@STUDENTS.STAMFOED.EDU'
,p_updated_by=>'2402230002@STUDENTS.STAMFOED.EDU'
);
end;
